import{_ as o,o as a,c as i,a3 as c}from"./chunks/framework.Ch_0qWu9.js";const f=JSON.parse('{"title":"ProofWidgets fixed npm dependency materials","description":"","frontmatter":{"sourcePath":"assets/environments/lean-base/proofwidgets-npm/README.md","sourceUrl":"https://github.com/MoonshotAI/TCSExam/blob/aab56977addd5d217972b7f35cf50be4440cb6c7/assets/environments/lean-base/proofwidgets-npm/README.md","alternateUrl":"/TCSExam/docs/zh/environments/lean-base/proofwidgets-npm/","alternateAnchors":{"proofwidgets-fixed-npm-dependency-materials":"proofwidgets-fixed-npm-dependency-materials","package-specific-notice-sources":"package-specific-notice-sources"}},"headers":[],"relativePath":"environments/lean-base/proofwidgets-npm/index.md","filePath":"environments/lean-base/proofwidgets-npm/index.md"}'),n={name:"environments/lean-base/proofwidgets-npm/index.md"};function s(t,e,d,r,l,p){return a(),i("div",null,[...e[0]||(e[0]=[c('<h1 id="proofwidgets-fixed-npm-dependency-materials" tabindex="-1">ProofWidgets fixed npm dependency materials <a class="header-anchor" href="#proofwidgets-fixed-npm-dependency-materials" aria-label="Permalink to &quot;ProofWidgets fixed npm dependency materials&quot;">​</a></h1><p>This directory covers all 387 non-root entries in the fixed ProofWidgets <code>package-lock.json</code>. The lock file is 172140 bytes with SHA-256 <code>3850e21b0823d6200db6da336ce1bd17a463db97ce314585ae47ed81a7327a7d</code>, matching ProofWidgets commit <code>b1436dc749e722c9920036b52cdc43b3451d0b69</code>.</p><p>Each <code>packages/&lt;lock-path&gt;/source.json</code> preserves the package name, fixed version, exact lock entry, official npm archive URL, SHA-512 integrity, archive SHA-256 and byte count, declared license, author, dev or platform-optional metadata, and notice provenance. Package archives and package binaries are not installed in this directory.</p><p>Notice files are organized by origin:</p><ul><li><code>notices/original/</code>: 364 files extracted from exact fixed npm archives.</li><li><code>notices/supplementary/</code>: 44 same-project or fixed-source supplemental notices. Each <code>source.json</code> records its URL, ref and applicable version or current-text scope.</li><li><code>notices/vendored/</code>: seven cliui vendored-module notices with an explicit mapping in <code>packages/@isaacs/cliui/vendored-modules.json</code>. Six come from corresponding fixed-lock packages, and eastasianwidth uses the fixed cliui source license.</li><li><code>notices/standard/</code>: one SPDX MIT text explaining the declared license of build-only <code>is-reference</code>.</li></ul><h2 id="package-specific-notice-sources" tabindex="-1">Package-specific notice sources <a class="header-anchor" href="#package-specific-notice-sources" aria-label="Permalink to &quot;Package-specific notice sources&quot;">​</a></h2><p><code>victory-vendor</code> 36.9.2 has no root LICENSE in its fixed archive, although its README declares MIT. Its 13 original lib-vendor D3 and Internmap notices remain separate. The project MIT text is supplemented from <code>victory@36.9.2</code> <code>package/LICENSE.txt</code>, with SHA-256 <code>34dee5fd5e5cc756efb5ad4d64652bce719bdf5e900ca5d7538253e737930bc4</code> and 1626 bytes, at <code>packages/victory-vendor/notices/supplementary/victory-36.9.2-LICENSE.txt</code>.</p><p>The cliui 9.0.0 archive has seven vendored module directories in both <code>dist/commonjs</code> and <code>dist/esm</code>. <code>packages/@isaacs/cliui/vendored-modules.json</code> maps all seven to their versions, fixed source, license URL, hash, and installed notice. <code>eastasianwidth</code> 0.3.0 uses the fixed cliui source <code>src/eastasianwidth/license</code>, with SHA-256 <code>94aa6016fb9d436508366433e9caba061443ca58f4c7eb515caec7badf90ae5a</code> and 1043 bytes. Its registry package.json and the cliui source function set support that version; the license is a fixed-source supplement, not an npm dist NOTICE.</p><p>The inventory covers the full lockfile, including 106 development dependencies and 26 platform-optional packages. These role fields describe how packages are installed or used during a build. Identifying which packages contribute to a generated JavaScript or WebAssembly bundle requires a separate review of that bundle and its build inputs. The records currently set <code>payload_linkage</code> to <code>not_asserted</code>; retain the complete notice and corresponding-source materials unless a bundle-specific review establishes a narrower set. The complete material set has 806 checksum entries in <code>SHA256SUMS</code>.</p><p>Obtain corresponding source from the pinned official URLs when required for redistribution, and retain the applicable notices for the containing image. Package installation and execution follow the upstream build instructions; this directory supplies source metadata and notices.</p>',10)])])}const u=o(n,[["render",s]]);export{f as __pageData,u as default};
